                <div class="card card-style bg-rgba" style="background: #fff">
                    <div class="content">
                        <div class="input-style input-style-2">
                            <span class="input-style-1-active" style="background: #fff;font-weight: bold;">设备UDID</span>
                            <em>
                                <a class="btn btn-xxs rounded-s text-uppercase font-900 shadow-s border-dark2-dark bg-dark2-light" id="getUDIDBtn">获取UDID</a>
                            </em>
                            <input type="text" id="udid" class="form-control" placeholder="请点击获取UDID（必须）" value="">
                        </div>
                        <div class="input-style input-style-2">
                            <span class="input-style-1-active" style="background: #fff;font-weight: bold;">选择软件</span>
                            <div id="applist" class="form-control " style="border-radius: 10px; height: 48px; line-height: 38px; font-size: 12px; background: #fff; cursor: pointer;">选择分类 | 选择软件</div>
                        </div>
                        <div class="input-style input-style-2">
                            <span class="input-style-1-active" style="background: #fff;font-weight: bold;">签名码</span>
                            <em>
                                <a href="https://wpa.qq.com/msgrd?v=3&amp;uin=1276117137&amp;site=qq&amp;menu=yes" target="_blank" class="btn btn-xxs rounded-s text-uppercase font-900 shadow-s border-dark-dark bg-dark2-light" >购买签名码</a>
                            </em>
                            <input type="text" id="code" class="form-control" placeholder="请输入签名码" value="">
                        </div>
                        <div class="accordion mt-2" id="accordion-6">
                            <div class="card card-style bg-green1-dark mb-4" style="margin: 0px 0px 30px 0px;">
                                <button class="btn accordion-btn border-0 bg-blue2-dark" data-toggle="collapse" data-target="#collapse200">
                                    <i class="fa fa-gear mr-2 text-warning"></i>点击设置 图标 | 标识 | 名称 -- 可忽略<i class="fa fa-chevron-down font-10 accordion-icon"></i>
                                </button>
                                <div id="collapse200" class="collapse bg-theme" data-parent="#accordion-6">
                                    <div class="p-3 color-theme">
                                        <p class="pb-0 mb-0 font-18"></p>
                                        <div class="input-style input-style-2">
                                            <span class="input-style-1-active" style="background: #fff;font-weight: bold;">修改图标</span>
                                            <input type="text" id="app_icon" class="form-control" maxlength="0" placeholder="从右侧上传图标，不上传即不修改" >
                                            <img id="tubiaoUploadBtn" style="position: absolute;top: 2px; right:4px;" width= 45px height=45px  src="{{ config('api.basics.cdn') }}/theme/dumpapp/index/images/icon.png" />
                                        </div>
                                        <div class="input-style input-style-2">
                                            <span class="input-style-1-active" style="background: #fff; font-weight: bold;">修改名称</span>
                                            <input type="text" id="app_name" class="form-control" placeholder="修改APP名称，可空，不懂请无视" value="">
                                        </div>
                                        <div class="input-style input-style-2">
                                            <span class="input-style-1-active" style="background: #fff; font-weight: bold;">修改标识</span>
                                            <em>
                                                <i id="app_bid_tip_btn" class="fa fa-question-circle text-warning"></i>
                                            </em>
                                            <input type="text" id="app_bid" class="form-control" placeholder="修改BundleId，可空，不懂请无视" value="">
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div id='appmiaoshu' class="card card-style bg-green1-dark mb-4" style="display: none; margin: 0px 0px 30px 0px; ">
                            <button class="btn accordion-btn border-0 color-white" data-toggle="collapse" data-target="#collapse12">
                                <i class="fa fa-star mr-2 "></i>
                                软件说明
                                <i class="fa fa-chevron-down font-10 accordion-icon"></i>
                            </button>
                            <div id="collapse12" class="collapse bg-theme show" data-parent="#accordion-6">
                                <div id='app_introduction' class="p-3 color-theme"></div>
                            </div>
                        </div>
                        <div id="dz1" style="display:none" class="input-group mb-2">
                            <div class="input-style input-style-2" style="width:100%;">
                                <span class="input-style-1-active" style="background: #fff; font-weight: bold;">初始数值</span>
                                <em>
                                    <i id="multiple_init_tip_btn" class="fa fa-question-circle text-warning"></i>
                                </em>
                                <input type="text" id="multiple_init" class="form-control" placeholder="设置多开初始数值，可空，不懂请无视" value="0">
                            </div>
                            <div class="input-style input-style-2" style="width:100%;">
                                <span class="input-style-1-active" style="background: #fff;font-weight: bold;">多开数量</span>
                                <input type="text" id="multiple_num" class="form-control" placeholder="设置多开软件数量，可空，不懂请无视" value="1">
                            </div>
                            <button style="width:100%;height: 50px; margin-top: 0rem !important;" type="button" class="btn btn-m mt-3 btn-full bg-green2-dark rounded-sm text-highlight font-900" id="signIPABtn1">开始安装</button>
                        </div>
                        <div id="dz2" style="display:none" class="input-group mb-2">
                            <button style="width:100%;" type="button" class="btn btn-m mt-3 btn-full bg-green2-dark rounded-sm text-highlight font-900" id="signIPABtn2">开始安装</button>
                        </div>
                    </div>
                </div>
            </div>

            <div id="Query" style="display: none;">
                <div class="card card-style bg-rgba" style="background: #fff">
                    <div class="content">
                        <div class="input-style input-style-2">
                            <span class="input-style-1-active" style="background: #fff;"><b>查询签名</b></span>
                            <em>
                                <a class="btn btn-xxs rounded-s text-uppercase font-900 shadow-s border-dark2-dark bg-dark2-light" id="getUDIDBtn2">获取UDID</a>
